export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RejectionReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

interface Rejection {
  provider: Provider;
  reason: RejectionReason;
}

interface InvalidCommandBody {
  code: "invalid_command";
}

interface NotFoundBody {
  code: "not_found";
}

interface AbortBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: Rejection[];
}

export interface ServiceResponse {
  status: number;
  body: PublicShipment | InvalidCommandBody | NotFoundBody | AbortBody;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | { kind: "confirmed"; bookingId: string }
  | { kind: "refused"; reason: RejectionReason }
  | { kind: "throttled"; retryAtMs: number }
  | { kind: "aborted"; classification: "unknown_failure" | "invalid_provider_response" };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isReason(value: unknown): value is RejectionReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: shipment.rejections.map(publicRejection),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: shipment.rejections.map(publicRejection),
  };
}

function publicRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map(publicRejection),
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: rejections.map(publicRejection),
  });
}

function repositoryAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  rejections: Rejection[],
): ServiceResponse {
  logAbort(dependencies, shipmentId, "repository", "repository_failure", rejections);
  return {
    status: 500,
    body: abortBody(shipmentId, "repository", "repository_failure", rejections),
  };
}

function parseAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (error.code === "cannot_ship") {
    return isReason(error.reason)
      ? { kind: "refused", reason: error.reason }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (error.code === "rate_limited") {
    return isValidFutureDeadline(error.retryAtMs, nowMs)
      ? { kind: "throttled", retryAtMs: error.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function parseBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    return isObject(error.details) && isReason(error.details.reason)
      ? { kind: "refused", reason: error.details.reason }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (error.type === "throttled") {
    return isObject(error.details) && isValidFutureDeadline(error.details.retryAtMs, nowMs)
      ? { kind: "throttled", retryAtMs: error.details.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function isValidFutureDeadline(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function parseConfirmation(provider: Provider, confirmation: unknown): CarrierOutcome {
  if (!isObject(confirmation)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas") {
    return typeof confirmation.bookingId === "string" && confirmation.bookingId.length > 0
      ? { kind: "confirmed", bookingId: confirmation.bookingId }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return typeof confirmation.reference === "string" && confirmation.reference.length > 0
    ? { kind: "confirmed", bookingId: confirmation.reference }
    : { kind: "aborted", classification: "invalid_provider_response" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return parseConfirmation(provider, confirmation);
  } catch (error) {
    return provider === "atlas"
      ? parseAtlasRejection(error, nowMs)
      : parseBeaconRejection(error, nowMs);
  }
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  decision: StoredShipment,
  status: number,
  event: Record<string, unknown>,
  rejectionsForSaveFailure: Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, decision);
  } catch {
    return repositoryAbort(dependencies, shipment.id, rejectionsForSaveFailure);
  }
  dependencies.logger.info(event);
  return { status, body: publicShipment(decision) };
}

async function dispatchFrom(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  nextProvider: Provider,
  retainedRejections: Rejection[],
): Promise<ServiceResponse> {
  const rejections = retainedRejections.map(publicRejection);
  let provider: Provider = nextProvider;
  const attempted = new Set<Provider>();

  while (!attempted.has(provider)) {
    attempted.add(provider);
    const outcome = await callCarrier(
      dependencies,
      provider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    if (outcome.kind === "confirmed") {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider,
        bookingId: outcome.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      return saveDecision(
        dependencies,
        shipment,
        dispatched,
        200,
        { shipmentId: shipment.id, action: "dispatched", provider },
        rejections,
      );
    }

    if (outcome.kind === "throttled") {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "deferred",
        nextProvider: provider,
        retryAtMs: outcome.retryAtMs,
        rejections: rejections.map(publicRejection),
      };
      return saveDecision(
        dependencies,
        shipment,
        deferred,
        202,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider,
          retryAtMs: outcome.retryAtMs,
          rejections: rejections.map(publicRejection),
        },
        rejections,
      );
    }

    if (outcome.kind === "aborted") {
      logAbort(dependencies, shipment.id, provider, outcome.classification, rejections);
      return {
        status: 500,
        body: abortBody(shipment.id, provider, outcome.classification, rejections),
      };
    }

    const refusal = { provider, reason: outcome.reason };
    rejections.push(refusal);
    if (provider === "atlas" && !rejections.some((entry) => entry.provider === "beacon")) {
      provider = "beacon";
      continue;
    }

    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections: rejections.map(publicRejection),
    };
    return saveDecision(
      dependencies,
      shipment,
      unavailable,
      422,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: rejections.map(publicRejection),
      },
      rejections,
    );
  }

  logAbort(dependencies, shipment.id, provider, "invalid_provider_response", rejections);
  return {
    status: 500,
    body: abortBody(shipment.id, provider, "invalid_provider_response", rejections),
  };
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return repositoryAbort(dependencies, command.shipmentId, []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // The host supplies only starter records and this service's JSON-compatible records.
    const shipment = value as StoredShipment;
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return dispatchFrom(
        dependencies,
        shipment,
        command,
        shipment.nextProvider,
        shipment.rejections,
      );
    }

    return dispatchFrom(dependencies, shipment, command, "atlas", []);
  }

  return { handle };
}
